luten-free", "dairy-optional"]}, {"name": "Crab Cake Benedict", "tags": ["gluten", "dairy"]}, {"name": "Grilled Veggie Plate", "tags": ["vegetarian", "vegan", "gluten-free"]}, {"name": "Shrimp & Grits", "tags": ["gluten-free", "dairy"]}], "slots": {"11:00": 5, "12:00": 5, "13:00": 5}}];
const size = Number(q.party_size || 1);
const earliest = q.earliest || '00:00', latest = q.latest || '23:59';
const out = [];
for (const r of RESTAURANTS) {
  const times = Object.entries(r.slots)
    .filter(([t, cap]) => t >= earliest && t <= latest && cap >= size)
    .map(([t]) => t).sort();
  if (times.length) out.push({ restaurant_id: r.id, name: r.name, cuisine: r.cuisine,
                               neighborhood: r.neighborhood, available_times: times });
}
return JSON.stringify(out);

